"use client";

// R42 seq22 (M28 FORM archetype, S3 module 3/3): the Work Progress entry form.
//
// R67 D-28 (R-071/R-078). The controls are now written out here rather than
// generated by FormSection/FieldRenderer, for three reasons the audit named and
// the generic renderer cannot serve:
//
//  1. ORDER. The field order has to read top-to-bottom as the site engineer
//     thinks -- Activity, BOQ line item, Date, Quantity done, % complete,
//     Entry basis -- and FormSection reorders by fieldStatus, always putting
//     every OPTIONAL field last.
//  2. "BOQ line item" WAS BURIED. Being optional, FormSection filed it under
//     "More details", collapsed by default -- so the one field the Work
//     Progress Report depends on was the one field nobody saw. It is now in the
//     main flow, labelled with what it is for. "More details" keeps exactly
//     what it should: Remarks and Site photo.
//  3. THE UNIT ADORNMENT. "Quantity done" is meaningless without the unit it is
//     counted in; FieldRenderer has no adornment slot at all.
//
// Everything NOT about layout is unchanged and deliberately so: the offline
// queue, the photo upload path, and the BOQ selector R47-005 added all behave
// exactly as before.
//
// Photo: uses the FILE control (new in this seq) + the now-exported
// uploadQueuedPhoto() from the offline queue -- see that function's own
// updated comment for the real online-path gap this closes.
//
// R67 D-55 / D-65 -- THE THREE SWALLOWED READS. This form's Activity select
// is REQUIRED, and its options came from
//
//     fetch(`/api/work-progress/activities?...`).then((r) => r.json())
//       .then((data) => setActivities(data.activities ?? []))
//       .catch(() => toast.error("Couldn't load activities"));
//
// so a failed read left the dropdown empty and "Log Entry" disabled with
// the reason "1 required field" -- the form blaming the site engineer for a
// backend failure they cannot act on. The BOQ read swallowed its failure
// entirely (`catch(() => {})`) and the line-item read silently set []. Same
// defect, and the same fix, as D-46 applied to ScheduleLogTimeClient: the
// failure is stated in words, it carries a Retry, and the disabled reason
// names the real cause.
import { readScopeHeaders } from "@/lib/scope-list-reads";
import { useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { ChevronDown, ChevronRight } from "lucide-react";
// R67 integration: the kit's FormScreen frame is kept; its FormSection /
// FieldRenderer generator is NOT, because D-28's three layout requirements
// above are exactly what a generic renderer cannot serve. The frame still
// owns the breadcrumb, the primary and the message band.
import { GuidedError, GuidedSubmitFailure } from "@/components/GuidedError";
import FaultPanel from "@/components/FaultPanel";
import { clearDraft, loadDraft, saveDraft } from "@/lib/error-guide/use-draft";
import { highlightElement, findFocusTarget } from "@/lib/error-guide/focus";
import { overHundredField, progressFaults, todayIso as localToday, type Fault } from "@/lib/error-guide/g2-faults";
import { currentScreen } from "@/lib/error-guide/context";
import { FormScreen, type FieldMessage } from "@fchecklist/veridian-ui-kit/screens";
import { FormField } from "@/components/ui/form-field";
import BoqLinePicker from "@/components/BoqLinePicker";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { PaneErrorCard } from "@/components/PaneState";
import { fetchJson, ApiError } from "@/lib/fetch-json";
import { useSubmit } from "@/lib/use-submit";
import { pickCurrentBoq } from "@/lib/work-progress-reads";
import { createClient } from "@/lib/supabase/client";
// R67 B-09 (DE-22): the required-field rule and the Save button's own words
// live beside the server's rule, not inside this component -- see that
// module's header for why.
import { missingFieldNames, missingProgressFields, submitLabelFor } from "@/lib/work-progress-form-fields";
import {
  enqueueWorkProgressEntry,
  listQueuedWorkProgressEntries,
  syncQueuedWorkProgressEntries,
  uploadQueuedPhoto,
  type QueuedWorkProgressEntry,
} from "@/lib/offline/work-progress-queue";

// R67 F-24: the page may hand this list down (see the `activities` prop), and
// the shared ProgressActivity leaves `unit` optional, so this does too. A row
// without one simply renders the bare name.
type Activity = { id: string; name: string; unit?: string | null };
type BoqLineItem = { id: string; itemCode: string | null; description: string; unit: string; rate: string };
type Boq = { id: string; version: number; status: string; title: string };
type ReadError = { status: number | null; message: string | null } | null;

/**
 * R67 D-28 lifted this field out of the collapsed "More details" where nobody
 * saw it; R67 B-09 then made it REQUIRED whenever the project is measured
 * against a BOQ, because createProgressEntry refuses such an entry outright
 * (BOQ_LINE_REQUIRED) and an entry with no line cannot be rolled up or valued.
 * The label follows the same condition the server enforces, so the form never
 * calls a field optional that the API will reject for being empty.
 */
export const BOQ_LINE_LABEL_REQUIRED = "BOQ line item (required - the Work Progress Report is priced off it)";
export const BOQ_LINE_LABEL_OPTIONAL = "BOQ line item (optional - this project has no BOQ to link to)";
export function boqLineLabelFor(projectHasBoq: boolean): string {
  return projectHasBoq ? BOQ_LINE_LABEL_REQUIRED : BOQ_LINE_LABEL_OPTIONAL;
}
export const PERCENT_HINT = "% of this BOQ line; the report uses quantity x rate for amounts";
export const ENTRY_BASIS_HINT = "Entry basis applies to both the quantity and the percent above.";
export const QUANTITY_PLACEHOLDER_NO_ACTIVITY = "Pick an activity first";

const ENTRY_BASIS_OPTIONS = [
  { value: "DELTA", label: "Delta -- this entry adds to progress already logged" },
  { value: "SNAPSHOT", label: "Snapshot -- this entry replaces the running total" },
];

function todayIso() {
  return localToday();
}

// GUIDED ERRORS (G2): what was typed survives leaving the form (a "Fix it now" link, a sign-in that ran out, a reload) -- see src/lib/error-guide/use-draft.ts.
// The chosen photo is kept too, when it is small enough to fit in session storage (a larger one is remembered by name and the person is asked to choose it again).
const DRAFT_PHOTO_MAX_BYTES = 1_500_000;
type DraftPhoto = { name: string; type: string; size: number; dataUrl: string | null };
type FormDraft = { values: Record<string, unknown>; photo: DraftPhoto | null };
const draftKeyFor = (projectId: string) => `work-progress-new:${projectId}`;

function readAsDataUrl(file: File): Promise<string | null> {
  return new Promise((resolve) => {
    try {
      const r = new FileReader();
      r.onload = () => resolve(typeof r.result === "string" ? r.result : null);
      r.onerror = () => resolve(null);
      r.readAsDataURL(file);
    } catch {
      resolve(null);
    }
  });
}

async function fileFromDraft(p: DraftPhoto): Promise<File | null> {
  if (!p.dataUrl) return null;
  try {
    const blob = await (await fetch(p.dataUrl)).blob();
    return new File([blob], p.name, { type: p.type || blob.type });
  } catch {
    return null;
  }
}


export default function WorkProgressFormClient({
  projectId,
  onLogged,
  activities: providedActivities,
}: {
  projectId: string;
  onLogged: () => void;
  /**
   * R67 F-24: the activity list the PAGE already read. Optional -- the form
   * still fetches for itself when it is mounted without one.
   */
  activities?: Activity[];
}) {
  // R67 D-28: Save lands the user ON the entry they just made.
  const router = useRouter();
  const [activities, setActivities] = useState<Activity[]>([]);
  // Sumeet live UAT 2026-10-13: a brand-new project has NO activities and the form had no way to make one (the backend POST existed, nothing called
  // it), so Work Progress -- and the progress cap, the report -- could not be used on a new project from the screen.
  const [firstActivityName, setFirstActivityName] = useState("");
  const [addingActivity, setAddingActivity] = useState(false);
  const [addActivityError, setAddActivityError] = useState<string | null>(null);
  const [lineItems, setLineItems] = useState<BoqLineItem[]>([]);
  // R47-005 (fault R46M13_TC30_01): every BOQ in the project, plus which one is
  // currently selected. Before this, the form resolved exactly ONE "current"
  // BOQ and offered no way to reach any other.
  const [boqs, setBoqs] = useState<Boq[]>([]);
  const [selectedBoqId, setSelectedBoqId] = useState<string | null>(null);
  // R67 D-55: what the two supporting reads said when they failed. Held, not
  // toasted -- a notification that fades cannot explain a control that is
  // still empty two minutes later.
  const [activitiesError, setActivitiesError] = useState<ReadError>(null);
  const [boqError, setBoqError] = useState<ReadError>(null);
  const [values, setValues] = useState<Record<string, unknown>>({ entryDate: todayIso(), entryBasis: "DELTA" });
  const [messages, setMessages] = useState<FieldMessage[]>([]);
  // R67 D-28: per-field messages, so a refusal appears where the field is as
  // well as in the band. `submitting` is NOT kept -- useSubmit owns that state
  // now, and two flags for one write is how a form ends up disabled forever.
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [scope, setScope] = useState<string | null>(null);
  const [queued, setQueued] = useState<QueuedWorkProgressEntry[]>([]);
  const [moreOpen, setMoreOpen] = useState(false);
  const [photo, setPhoto] = useState<File | null>(null);
  // GUIDED ERRORS (G2): faults the form found itself (nothing was sent), shown as the guide panel AND on the field; "attempted" turns on the
  // "missing" messages, which would be noise while the person is still filling the form in.
  const [attempted, setAttempted] = useState(false);
  const [restored, setRestored] = useState(false);
  const [photoToChoose, setPhotoToChoose] = useState<string | null>(null);
  const [draftReady, setDraftReady] = useState(false);
  // The entry was saved but its photo was not: the person stays here with a way to send the photo again.
  const [photoFailed, setPhotoFailed] = useState<{ entryId: string; file: File } | null>(null);
  const draftKey = draftKeyFor(projectId);

  // Put back what was typed before the person left this form (and say so, so a surprise is never silent).
  useEffect(() => {
    const saved = loadDraft<FormDraft>(draftKey);
    if (saved && saved.values && Object.keys(saved.values).length > 0) {
      setValues((v) => ({ ...v, ...saved.values }));
      setRestored(true);
      if (saved.values.remarks) setMoreOpen(true);
    }
    if (saved?.photo) {
      setMoreOpen(true);
      void fileFromDraft(saved.photo).then((f) => {
        if (f) setPhoto(f);
        else setPhotoToChoose(saved.photo!.name);
      });
    }
    setDraftReady(true);
  }, [draftKey]);

  // Keep the draft in step with the form (only after the first restore, so an empty first render cannot wipe a saved draft).
  useEffect(() => {
    if (!draftReady) return;
    const { photo: _drop, boqId: _boq, ...plain } = values as Record<string, unknown>;
    const meaningful = Object.entries(plain).some(([k, v]) => k !== "entryDate" && k !== "entryBasis" && v !== undefined && v !== "") || !!photo;
    if (!meaningful) { clearDraft(draftKey); return; }
    let live = true;
    (async () => {
      let p: DraftPhoto | null = null;
      if (photo) p = { name: photo.name, type: photo.type, size: photo.size, dataUrl: photo.size <= DRAFT_PHOTO_MAX_BYTES ? await readAsDataUrl(photo) : null };
      else if (photoToChoose) p = { name: photoToChoose, type: "", size: 0, dataUrl: null };
      if (live) saveDraft<FormDraft>(draftKey, { values: plain, photo: p });
    })();
    return () => { live = false; };
  }, [values, photo, photoToChoose, draftKey, draftReady]);

  useEffect(() => {
    let cancelled = false;
    createClient().auth.getUser().then(({ data }) => { if (!cancelled) setScope(data.user?.id ?? null); });
    return () => { cancelled = true; };
  }, []);

  const refreshQueued = useCallback(async () => {
    if (!scope) return;
    setQueued(await listQueuedWorkProgressEntries(scope));
  }, [scope]);

  useEffect(() => { refreshQueued(); }, [refreshQueued]);

  const loadActivities = useCallback(async () => {
    setActivitiesError(null);
    try {
      const data = await fetchJson<{ activities?: Activity[] }>(
        `/api/work-progress/activities?projectId=${encodeURIComponent(projectId)}`
      );
      setActivities(data.activities ?? []);
    } catch (err) {
      setActivities([]);
      setActivitiesError({
        status: err instanceof ApiError ? err.status : null,
        message: err instanceof Error ? err.message : null,
      });
    }
  }, [projectId]);

  async function addFirstActivity() {
    const name = firstActivityName.trim();
    if (!name) { setAddActivityError("Name the activity first, for example Brick partition."); return; }
    setAddingActivity(true);
    setAddActivityError(null);
    try {
      const created = await fetchJson<{ id: string }>("/api/work-progress/activities", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ projectId, name }),
      });
      setFirstActivityName("");
      await loadActivities();
      if (created?.id) setField("activityId", created.id);
    } catch (err) {
      setAddActivityError(err instanceof Error && err.message ? `The activity was not added: ${err.message}` : "The activity was not added.");
    } finally {
      setAddingActivity(false);
    }
  }

  // R67 MERGE (lane F2's F-24). This form used to fetch
  // /api/work-progress/activities while WorkProgressPageClient fetched exactly
  // the same list alongside it -- two requests, one screen, one answer. When
  // the page hands its list down, the form uses it and asks for nothing; the
  // fetch above still runs for the case the page cannot cover (a Retry beside
  // the field, and any future mounting of this form on its own).
  const suppliedActivities = providedActivities ?? null;
  useEffect(() => {
    if (suppliedActivities) {
      setActivities(suppliedActivities);
      setActivitiesError(null);
      return;
    }
    void loadActivities();
  }, [suppliedActivities, loadActivities]);

  useEffect(() => {
    // R47-005 (fault R46M13_TC30_01, reproduced live in production 2026-08-25):
    // this used to resolve ONE "current" BOQ -- approved, else submitted, else
    // highest version -- fetch only that BOQ's line items, and offer no BOQ
    // selector anywhere on the form. Every other BOQ in the project was
    // therefore unreachable for recording progress against.
    //
    // Measured on Oakwood Residence at the time: 31 BOQs carrying 79 line items
    // in the project, and the picker offered TWO ("PP1 -- Parent PP1",
    // "PP1-A -- Child A"). The winner was an unrelated leftover test BOQ,
    // "R45-B3 pct-only 1787594876935", which won on ONE property: it was the
    // only version-2 row. The project has zero approved and zero submitted
    // BOQs, so both preference branches missed and resolution fell through to
    // version DESC. A freshly created BOQ is draft/version 1 and could NEVER
    // outrank it -- so a user who had just built a weighted BOQ could not
    // select its sub-task at all. That is TC-30, unrunnable by a real user.
    //
    // The resolution order is KEPT as the DEFAULT selection (so the common
    // single-BOQ case behaves exactly as before), but the full list is now
    // retained and offered whenever the project holds more than one -- the
    // same shape projexa#94 already established for the work-progress REPORT,
    // rather than inventing a second convention for the same problem.
    let cancelled = false;
    (async () => {
      try {
        const data = await readScopeHeaders<Boq>(projectId);
        if (cancelled) return;
        const all: Boq[] = data.boqs ?? [];
        setBoqError(null);
        if (all.length === 0) return;
        setBoqs(all);
        // R67 D-55: the approved > submitted > highest-version rule was
        // written out here for the third time in this module. It is
        // pickCurrentBoq() now, tested once, so the form and the two list
        // screens cannot disagree about which revision a line belongs to.
        const current = pickCurrentBoq(all);
        if (!current) return;
        setSelectedBoqId(current.id);
        setValues((v) => ({ ...v, boqId: current.id }));
      } catch (err) {
        // The BOQ link is genuinely optional -- an entry can be logged
        // against an activity alone -- so this does not block the form. But
        // it is no longer SILENT: a QS who cannot find their line needs to
        // know the list failed to load rather than concluding the BOQ is
        // missing from the project.
        if (cancelled) return;
        setBoqError({
          status: err instanceof ApiError ? err.status : null,
          message: err instanceof Error ? err.message : null,
        });
      }
    })();
    return () => { cancelled = true; };
  }, [projectId]);

  // Loads the selected BOQ's line items. Org and project scoping are unchanged:
  // this only ever fetches a BOQ id that /api/scope?projectId= already returned
  // for this project, and that route is org-scoped server-side.
  useEffect(() => {
    if (!selectedBoqId) return;
    let cancelled = false;
    (async () => {
      try {
        const boq = await fetchJson<{ lineItems?: BoqLineItem[] }>(`/api/scope/${encodeURIComponent(selectedBoqId)}`);
        if (!cancelled) {
          setLineItems(boq.lineItems ?? []);
          setBoqError(null);
        }
      } catch (err) {
        // Same rule as the BOQ list above: the picker empties, and the user
        // is told why rather than being left to read an empty dropdown as
        // "this BOQ has no lines".
        if (cancelled) return;
        setLineItems([]);
        setBoqError({
          status: err instanceof ApiError ? err.status : null,
          message: err instanceof Error ? err.message : null,
        });
      }
    })();
    return () => { cancelled = true; };
  }, [selectedBoqId]);

  const selectedActivity = activities.find((a) => a.id === values.activityId);
  const selectedLine = lineItems.find((l) => l.id === values.boqLineItemId);
  // The BOQ line's unit wins when a line is chosen, exactly as VERIDIAN's own
  // resolveProgressUnit() decides it for the list and the report -- one rule,
  // not a screen-local second opinion.
  const unit = selectedLine?.unit ?? selectedActivity?.unit ?? null;

  // R67 B-09: whether THIS project is measured against a BOQ at all. The
  // /api/scope fetch below already answers it, so this needs no extra call.
  const projectHasBoq = boqs.length > 0;
  const missingRequired = missingProgressFields(values, projectHasBoq);
  // Every fault in what is typed, in screen order. The "missing" ones are only SHOWN after a first press of Log Entry; the others (a percentage
  // of 140, a date in the future, a photo that is too big) are shown beside the field the moment they exist.
  const faults: Fault[] = progressFaults(
    { ...values, photo: photo ? { name: photo.name, size: photo.size, type: photo.type } : null },
    { projectHasBoq, hasActivities: activities.length > 0 }
  );
  const isMissingCode = (c: string) => /_MISSING$|^WP_NO_ACTIVITIES$/.test(c);
  const shownFaults = faults.filter((f) => attempted || !isMissingCode(f.code));
  const faultMsg = (field: string) => shownFaults.find((f) => f.field === field)?.message;
  // The server's "more than 100%" refusal belongs beside the number that caused it.
  const serverFieldMessage = (field: string) => {
    const f = submit.failure;
    return f && overHundredField(f.serverMessage) === field ? f.serverMessage : undefined;
  };


  function setField(field: string, value: unknown) {
    if (field === "boqId") {
      // Switching BOQ invalidates the line selected from the previous one, so
      // clear it. Leaving a stale line id in place would post progress against
      // a line the user can no longer see.
      setSelectedBoqId(value as string);
      setValues((v) => ({ ...v, boqId: value, boqLineItemId: undefined }));
      return;
    }
    setValues((v) => ({ ...v, [field]: value }));
    setFieldErrors((e) => (e[field] ? { ...e, [field]: "" } : e));
  }

  /** What this form is about to send, from the values as they stand. */
  function currentPayload() {
    return {
      projectId,
      activityId: values.activityId as string,
      boqLineItemId: (values.boqLineItemId as string) || undefined,
      entryDate: values.entryDate as string,
      quantityDone: Number(values.quantityDone),
      percentComplete: Number(values.percentComplete),
      entryBasis: values.entryBasis as "DELTA" | "SNAPSHOT",
      remarks: (values.remarks as string) || undefined,
    };
  }

  function currentPhoto(): File | null {
    return photo;
  }

  function resetForm() {
    setValues({ entryDate: todayIso(), entryBasis: "DELTA" });
    setPhoto(null);
    setPhotoToChoose(null);
    setAttempted(false);
    clearDraft(draftKey);
    onLogged();
  }

  /** Puts the entry on this device and clears the form, as if it had landed. */
  async function queueOnDevice(reason: string): Promise<boolean> {
    if (!scope) {
      setMessages([{ level: "error", text: "Still verifying your session -- try again in a moment" }]);
      return false;
    }
    const photo = currentPhoto();
    await enqueueWorkProgressEntry(scope, {
      ...currentPayload(),
      photo: photo ? { blob: photo, name: photo.name, type: photo.type } : null,
    });
    setMessages([{ level: "info", text: reason }]);
    resetForm();
    refreshQueued();
    return true;
  }

  // R67 D-72: the online write goes through the one submit -- so it carries a
  // ten-second ceiling (it had none), and a refusal stays on the screen
  // instead of being a toast that faded while the site engineer was looking
  // at the entry they had just typed.
  const submit = useSubmit<{ id?: string }>({
    objectLabel: "progress entry",
    buildRequest: () => ({
      input: "/api/work-progress",
      init: {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(currentPayload()),
      },
    }),
    onSuccess: async (created) => {
      const photo = currentPhoto();
      // R42 seq22 fix: the online path never uploaded a photo before this --
      // see uploadQueuedPhoto()'s own comment for the full finding.
      if (photo && created?.id) {
        let photoOk = true;
        await uploadQueuedPhoto(created.id, { blob: photo, name: photo.name, type: photo.type }).catch(() => { photoOk = false; });
        if (!photoOk) {
          // The entry IS saved; only the picture is not. Stay here, say exactly that, and offer the photo again -- never a silent "logged".
          setPhotoFailed({ entryId: created.id, file: photo });
          clearDraft(draftKey);
          setValues({ entryDate: todayIso(), entryBasis: "DELTA" });
          setPhoto(null);
          onLogged();
          return;
        }
      }
      resetForm();
      // R67 D-28: Save used to leave the user on an emptied form, with no way
      // to see the thing they had just made. They now land on it, and the
      // object page reads ?logged=1 as its receipt. resetForm() still runs
      // first, so a Back to this pane finds a clean form rather than the
      // values that were just written.
      if (created?.id) router.push(`/work-progress/${created.id}?logged=1`);
    },
    // A dropped connection is not a failure on this form: the entry is kept
    // on the device and synced when the radio comes back. That is a real
    // second outcome, which is why the hook asks rather than assuming.
    onTransportError: async (err) =>
      err instanceof TypeError
        ? queueOnDevice("Network unavailable -- progress saved on this device, will sync automatically")
        : false,
  });

  async function handleSubmit() {
    setAttempted(true);
    if (faults.length > 0) {
      // Nothing is sent. The guide panel says what is wrong and what to do; the first wrong field is outlined and focused now.
      setMessages([]);
      const el = findFocusTarget(faults[0].field);
      if (faults[0].field === "wp-photo") setMoreOpen(true);
      if (el) highlightElement(el);
      return;
    }
    setMessages([]);

    if (typeof navigator !== "undefined" && !navigator.onLine) {
      await queueOnDevice("You're offline -- progress saved on this device, will sync automatically");
      return;
    }

    // R67 D-72: the write itself, its ten-second ceiling, its offline
    // fallback and its refusal all live in useSubmit -- including WS-B's rule
    // that a coded refusal is rendered through the shared dictionary
    // ("Pick a BOQ line", never "boqLineItemId"), which is applied there so
    // every create form obeys it rather than this one screen.
    submit.submit();
  }

  useEffect(() => {
    if (!scope) return;
    const run = () => { if (typeof navigator !== "undefined" && navigator.onLine) syncQueuedWorkProgressEntries(scope).then(({ synced }) => { if (synced > 0) { toast.success(`Synced ${synced} queued ${synced === 1 ? "entry" : "entries"}`); onLogged(); } refreshQueued(); }); };
    run();
    window.addEventListener("online", run);
    return () => window.removeEventListener("online", run);
  }, [scope]);

  // R42 seq23 live-user finding: same fail-after-click gap caught on
  // Permits' Save applies here too -- Log Entry was clickable with required
  // fields still empty. See PermitObjectClient.tsx's own comment for the
  // GLOBAL rule this violated.
  //
  // R67 B-09: `boqLineItemId` joins the list whenever the project has a BOQ,
  // which is exactly the rule the API route enforces -- so the button is
  // disabled for the same reason the server would have refused, instead of
  // the user finding out after the click.
  const missingCount = missingRequired.length;

  // R67 D-55 (the rule D-46 wrote for ScheduleLogTimeClient): when the
  // Activity list failed to load, Activity is unfillable, and telling the
  // user they have "1 required field" left is blaming them for a backend
  // failure. Name the real cause instead.
  const submitDisabledReason = activitiesError ? "Activities could not be loaded" : undefined;

  const banner = (
    <>
      {activitiesError && (
        <div className="mx-4 mt-3">
          <PaneErrorCard
            entity="this project's activities"
            error={activitiesError}
            onRetry={() => void loadActivities()}
          />
        </div>
      )}
      {boqError && (
        <div className="mx-4 mt-3">
          <PaneErrorCard entity="this project's BOQ lines" error={boqError} />
        </div>
      )}
      {queued.length > 0 && (
        <div className="mx-4 mt-3 rounded-md border border-amber-300 bg-amber-50 px-3 py-2 text-[12.5px] text-amber-900">
          {queued.length} {queued.length === 1 ? "entry" : "entries"} queued on this device, will sync automatically.
        </div>
      )}
    </>
  );

  return (
    <FormScreen
      breadcrumb="Work Progress / Log entry"
      title="Log Work Progress"
      onSubmit={handleSubmit}
      // R67 B-09 (DE-22): the button NAMES what is still needed rather than
      // counting it -- "2 required fields missing" makes the user hunt.
      submitLabel={submitLabelFor(missingRequired)}
      submitting={submit.saving}
      submitDisabled={Boolean(activitiesError) || submit.saving}
      submitDisabledReason={submitDisabledReason}
      // The failure is a MESSAGE on the screen, not a notification: the kit's
      // message area persists until the next submit, which is the whole point
      // of moving off toast.error().
      messages={messages} // the hook's failure is shown by <GuidedSubmitFailure> below
      banner={activitiesError || boqError || queued.length > 0 ? banner : undefined}
    >
      <div className="space-y-3 px-4 pt-3 empty:hidden">
        {restored && !submit.failure && (
          <p role="status" data-testid="wp-draft-restored" className="rounded-md border border-px-info-border bg-px-info-light px-3 py-2 text-[12.5px] text-px-info">
            We put back what you had typed here before you left. Check it, then press Log Entry.
            {photoToChoose ? ` Your photo "${photoToChoose}" was too big to keep; choose it again under More details.` : ""}
          </p>
        )}
        <FaultPanel faults={shownFaults} draftKey={draftKey} />
        <GuidedSubmitFailure
          failure={submit.failure ? { ...submit.failure, field: submit.failure.field ?? overHundredField(submit.failure.serverMessage) } : null}
          onRetry={submit.submit}
          draftKey={draftKey}
        />
        {photoFailed && (
          <GuidedError
            ctx={{ ...currentScreen(), projectId, entityId: photoFailed.entryId, entityType: "work_progress_entry", status: 0, code: "WP_PHOTO_UPLOAD_FAILED", serverMessage: `The entry was saved, but the photo "${photoFailed.file.name}" did not upload.` }}
            onRetry={() => {
              const pf = photoFailed;
              void uploadQueuedPhoto(pf.entryId, { blob: pf.file, name: pf.file.name, type: pf.file.type })
                .then(() => { setPhotoFailed(null); router.push(`/work-progress/${pf.entryId}?logged=1`); })
                .catch(() => { /* the panel stays; the person can try again or open the saved entry */ });
            }}
            retryable
          />
        )}
      </div>
      <section className="border-t border-ct-border px-4 py-3">
        <h3 className="mb-3 text-[13px] font-medium text-ct-navy">Progress entry</h3>
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
          <FormField label="Activity" required error={fieldErrors.activityId || faultMsg("wp-activity")}>
            {(props) => (
              <Select value={(values.activityId as string) ?? ""} onValueChange={(v) => setField("activityId", v)}>
                <SelectTrigger {...props} data-testid="wp-activity"><SelectValue placeholder="Choose an activity" /></SelectTrigger>
                <SelectContent>
                  {activities.map((a) => (
                    <SelectItem key={a.id} value={a.id}>{a.unit ? `${a.name} (${a.unit})` : a.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </FormField>

          {activities.length === 0 && !activitiesError && (
            <div data-testid="first-activity" className="sm:col-span-2 rounded-md border border-ct-border p-3">
              <p className="text-[12px] text-ct-muted">This project has no activities yet. Add the first one to start recording progress.</p>
              <div className="mt-2 flex flex-wrap items-start gap-2">
                <Input
                  data-testid="first-activity-name"
                  aria-label="Name of the first activity"
                  className="max-w-sm"
                  placeholder="e.g. Brick partition"
                  value={firstActivityName}
                  onChange={(e) => setFirstActivityName(e.target.value)}
                  disabled={addingActivity}
                />
                <button type="button" data-testid="first-activity-add" className="h-9 rounded-md border border-ct-border px-3 text-sm font-medium" onClick={() => void addFirstActivity()} disabled={addingActivity}>
                  {addingActivity ? "Adding…" : "Add activity"}
                </button>
              </div>
              {addActivityError ? <p role="alert" className="mt-1 text-[12px] text-px-error">{addActivityError}</p> : null}
            </div>
          )}

          {/* Shown only when the project actually holds more than one BOQ --
              with a single BOQ the choice is not a choice (projexa#94's rule). */}
          {boqs.length > 1 && (
            <FormField label="BOQ">
              {(props) => (
                <Select value={(values.boqId as string) ?? ""} onValueChange={(v) => setField("boqId", v)}>
                  <SelectTrigger {...props}><SelectValue placeholder="Choose a BOQ" /></SelectTrigger>
                  <SelectContent>
                    {[...boqs]
                      .sort((a, b) => b.version - a.version || a.title.localeCompare(b.title))
                      .map((b) => <SelectItem key={b.id} value={b.id}>{`${b.title} (v${b.version}, ${b.status})`}</SelectItem>)}
                  </SelectContent>
                </Select>
              )}
            </FormField>
          )}

          <FormField
            label={boqLineLabelFor(projectHasBoq)}
            required={projectHasBoq}
            error={fieldErrors.boqLineItemId || faultMsg("wp-boq-line")}
            className="sm:col-span-2"
            hint={selectedLine ? `${selectedLine.description} · ${selectedLine.unit} · rate ${selectedLine.rate}` : undefined}
          >
            {/* R67 lane D22 (item D-64, rec R-230), folded in at the
                integration merge. WHAT THIS REPLACES: a native <select>
                holding every line in the BOQ, labelled by description alone,
                in insertion order -- on a 128-line BOQ that is a scroll, not a
                choice, and it gave no way to tell a PARENT line (whose
                quantity is delivered through its children and cannot be
                recorded against) from an ordinary one, so picking the wrong
                one was silent. The picker searches server-side over
                /api/scope/lines on both code and description, and shows parent
                lines disabled WITH the reason rather than hiding them.

                WHY THIS IS THE BOQ LINE FIELD AND NOT "Activity": the item
                names the Daily Entry's Activity select, but the endpoint it
                specifies returns BOQ lines, and "parent lines disabled" is a
                BOQ-line property -- construction_activities has no hierarchy,
                and activity_id is a separate NOT NULL FK, so swapping the
                Activity control would make every submission fail.

                NOT folded in, and named rather than dropped quietly: D-64 also
                wanted the whole-BOQ download gone. The /api/scope/{id} read
                above stays, because D-55's hint line and its stated failure
                state are both built from it. The picker removes the
                unsearchable list; removing that read is a follow-up. */}
            {/* 2026-09-08 -- REAL BUG FOUND (R80 E2E-rewrite sweep): this
                render prop ignored FormField's own `props` entirely (every
                sibling field in this form destructures it, e.g. the Date
                field two blocks below spreads `{...props}` onto its
                <Input>) -- so FormField's <Label htmlFor={id}> pointed at
                an id nothing on screen carried, AND BoqLinePicker's own
                SearchSelect draws its accessible name from a fixed internal
                `aria-label` ("BOQ line"), which wins over any native label
                association per the ARIA spec regardless. A screen reader
                announced only "BOQ line", never the fuller, more
                informative visible label ("BOQ line item ..." /
                "BOQ line item (optional) ..."). BoqLinePicker/SearchSelect
                have no `id` prop to receive FormField's `id` even if this
                threaded it through, so the fix that actually closes the
                announced-name gap is passing the SAME text the visible
                <Label> already renders as this control's own `ariaLabel`,
                overriding its "BOQ line" default. */}
            {() => (
              <div data-testid="wp-boq-line" tabIndex={-1}>
                <BoqLinePicker
                  projectId={projectId}
                  boqId={selectedBoqId}
                  value={(values.boqLineItemId as string) ?? null}
                  onChange={(lineId) => setField("boqLineItemId", lineId ?? "")}
                  ariaLabel={boqLineLabelFor(projectHasBoq)}
                />
              </div>
            )}
          </FormField>

          <FormField label="Date" required error={fieldErrors.entryDate || faultMsg("wp-date")}>
            {(props) => (
              <Input {...props} data-testid="wp-date" type="date" max={todayIso()} value={(values.entryDate as string) ?? ""} onChange={(e) => setField("entryDate", e.target.value)} />
            )}
          </FormField>

          {/* The unit sits INSIDE the control, because a quantity typed with no
              unit in sight is the mis-keying this module keeps producing. */}
          <FormField label="Quantity done" required error={fieldErrors.quantityDone || faultMsg("wp-quantity") || serverFieldMessage("wp-quantity")}>
            {(props) => (
              <div className="relative">
                <Input
                  {...props}
                  data-testid="wp-quantity"
                  type="number"
                  inputMode="decimal"
                  min={0}
                  className={unit ? "pr-14" : undefined}
                  placeholder={selectedActivity ? undefined : QUANTITY_PLACEHOLDER_NO_ACTIVITY}
                  value={(values.quantityDone as string) ?? ""}
                  onChange={(e) => setField("quantityDone", e.target.value)}
                />
                {unit && (
                  <span className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-[12px] text-px-muted">{unit}</span>
                )}
              </div>
            )}
          </FormField>

          <FormField label="% complete" required hint={PERCENT_HINT} error={fieldErrors.percentComplete || faultMsg("wp-percent") || serverFieldMessage("wp-percent")}>
            {(props) => (
              <Input
                {...props}
                data-testid="wp-percent"
                type="number"
                inputMode="decimal"
                min={0}
                max={100}
                value={(values.percentComplete as string) ?? ""}
                onChange={(e) => setField("percentComplete", e.target.value)}
              />
            )}
          </FormField>

          <FormField label="Entry basis" required hint={ENTRY_BASIS_HINT} className="sm:col-span-2">
            {(props) => (
              <RadioGroup
                aria-describedby={props["aria-describedby"]}
                aria-required={props["aria-required"]}
                value={(values.entryBasis as string) ?? "DELTA"}
                onValueChange={(v) => setField("entryBasis", v)}
                className="gap-1.5"
              >
                {ENTRY_BASIS_OPTIONS.map((option) => (
                  <div key={option.value} className="flex items-center gap-2">
                    <RadioGroupItem value={option.value} id={`${props.id}-${option.value}`} />
                    <Label htmlFor={`${props.id}-${option.value}`} className="text-[12.5px] font-normal">{option.label}</Label>
                  </div>
                ))}
              </RadioGroup>
            )}
          </FormField>
        </div>

        {/* "More details" now holds exactly what it should: the two fields a
            site engineer genuinely may skip. */}
        <div className="mt-3">
          <button
            type="button"
            onClick={() => setMoreOpen((v) => !v)}
            className="inline-flex items-center gap-1 text-[12.5px] text-ct-muted hover:text-ct-navy"
          >
            {moreOpen ? <ChevronDown className="size-3.5" /> : <ChevronRight className="size-3.5" />}
            More details
          </button>
          {moreOpen && (
            <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-2">
              <FormField label="Remarks" className="sm:col-span-2">
                {(props) => (
                  <Textarea {...props} data-testid="wp-remarks" rows={3} value={(values.remarks as string) ?? ""} onChange={(e) => setField("remarks", e.target.value)} />
                )}
              </FormField>
              <FormField label="Site photo" className="sm:col-span-2" error={faultMsg("wp-photo")} hint={photo ? `Selected: ${photo.name}` : photoToChoose ? `Choose "${photoToChoose}" again` : undefined}>
                {(props) => (
                  <Input {...props} data-testid="wp-photo" type="file" accept="image/*" onChange={(e) => { setPhotoToChoose(null); setPhoto(e.target.files?.[0] ?? null); }} />
                )}
              </FormField>
            </div>
          )}
        </div>
      </section>
    </FormScreen>
  );
}
